function ilConstellationV2(sil,stage,opt){ opt=opt||{}; var U=opt.uid||('c'+(sil.name||'x')),N={hatchling:5,young:8,grown:13,wise:21}, R=[1.35,1.8,2.35],n=N[stage]||13,hx=sil.heart[0],hy=sil.heart[1],hi=sil.heartI, stars=sil.stars,grow=sil.grow,order=sil.order,A='#E6B454',T='#FFF6D8'; function f(n){return(+n).toFixed(1).replace(/\.0$/,'')} function ell(p,fill,sw,st,ex){var t=p.rot?' transform="rotate('+f(p.rot)+' '+f(p.c[0])+' '+f(p.c[1])+')"':'';ex=ex||'';return p.kind==='path'?'<path d="'+p.d+'" fill="'+fill+'" stroke="'+st+'" stroke-width="'+f(sw)+'" stroke-linejoin="round"'+ex+'/>':'<ellipse cx="'+f(p.c[0])+'" cy="'+f(p.c[1])+'" rx="'+f(p.r[0])+'" ry="'+f(p.r[1])+'"'+t+' fill="'+fill+'" stroke="'+st+'" stroke-width="'+f(sw)+'"'+ex+'/>'} function hit(x0,y0,x1,y1,cx,cy,rx,ry){for(var i=0,t,x,y;i<=8;i++){t=i/8;x=x0+(x1-x0)*t;y=y0+(y1-y0)*t;if(((x-cx)/rx)**2+((y-cy)/ry)**2<=1)return 1}return 0} var vis=[],i,seen={};for(i=0;i<grow.length&&vis.length<n;i++)if(!seen[grow[i]]){seen[grow[i]]=1;vis.push(grow[i])} if(vis.indexOf(hi)<0)vis[vis.length-1]=hi; var fa=sil.face,fx,fy,frx,fry; if(fa.kind==='shell'){fx=fa.hx;fy=fa.hy;frx=fa.hrx*1.08;fry=fa.hry*1.12}else{fx=(fa.lx+fa.rx)/2;fy=(fa.ly+fa.ry)/2;frx=Math.abs(fa.rx-fa.lx)/2+(fa.r||3)*1.5;fry=(fa.r||3)*2.2+5} var defs='<radialGradient id="'+U+'G" cx="50%" cy="55%" r="50%"><stop offset="0" stop-color="'+A+'" stop-opacity=".4"/><stop offset="1" stop-color="'+A+'" stop-opacity="0"/></radialGradient>'; var chip='<rect class="il-sky-chip" x="8" y="8" width="184" height="184" rx="22" fill="#120E18"/>'; var glow='<ellipse class="il-glow" cx="'+f(sil.body[0])+'" cy="'+f(sil.body[1])+'" rx="'+f(sil.body[2]*1.35)+'" ry="'+f(sil.body[3]*1.45)+'" fill="url(#'+U+'G)"/>'; var fill=sil.parts.map(function(p){return ell(p,'#E6B454',0,'none',' opacity=".11"')+ell(p,'none',1.5,'#D9C9A8',' opacity=".42" stroke-dasharray="2.2 2.4"')}).join(''); var ord=order.filter(function(i){return vis.indexOf(i)>=0}),segs='',a,b,p; for(i=0;i<ord.length-1;i++){a=stars[ord[i]];b=stars[ord[i+1]];if(!hit(a[0],a[1],b[0],b[1],fx,fy,frx*.92,fry*.92))segs+='M'+f(a[0])+' '+f(a[1])+'L'+f(b[0])+' '+f(b[1])} var dots=vis.filter(function(i){return i!==hi}).map(function(i){p=stars[i];return'<circle cx="'+f(p[0])+'" cy="'+f(p[1])+'" r="'+R[p[2]||1]+'" fill="'+T+'"/>'}).join(''); var heart='<circle cx="'+f(hx)+'" cy="'+f(hy)+'" r="8" fill="'+A+'" opacity=".3"/><circle cx="'+f(hx)+'" cy="'+f(hy)+'" r="4.4" fill="'+T+'" stroke="'+A+'" stroke-width="1.2"/>'; var ant=sil.ant?'<path d="'+sil.ant.map(function(s){return'M'+s[0][0]+' '+s[0][1]+'L'+s[1][0]+' '+s[1][1]}).join('')+'" fill="none" stroke="#D9C9A8" stroke-width="1.3" stroke-linecap="round" opacity=".85"/>':''; return '<defs>'+defs+'</defs>'+chip+glow+fill+(segs?'<path d="'+segs+'" fill="none" stroke="#D9C9A8" stroke-width="1.15" stroke-linecap="round" opacity=".82"/>':'')+ant+dots+heart}
